queries:
WITH g AS (
  SELECT c.gender AS gender, COUNT(DISTINCT o.order_id) AS cnt
  FROM Invoices i
  JOIN Orders o ON i.order_id = o.order_id
  JOIN Customers c ON o.customer_id = c.customer_id
  GROUP BY c.gender
),
a AS (
  SELECT AVG(cnt) AS avg_cnt FROM g
)
SELECT AVG(g.cnt) AS avg_count, AVG(g.cnt - a.avg_cnt) AS avg_diff
FROM g, a
WHERE g.cnt > a.avg_cnt;
SELECT AVG(cnt) FROM (SELECT c.gender, COUNT(DISTINCT i.order_id) AS cnt FROM Customers c LEFT JOIN Orders o ON c.customer_id = o.customer_id LEFT JOIN Invoices i ON o.order_id = i.order_id GROUP BY c.gender)
SELECT AVG(cnt) FROM (SELECT c.gender, COUNT(DISTINCT o.order_id) AS cnt FROM Customers c JOIN Orders o ON c.customer_id = o.customer_id JOIN Invoices i ON i.order_id = o.order_id GROUP BY c.gender);
SELECT NULLIF(gender, '') AS gender, COUNT(*) FROM Customers GROUP BY NULLIF(gender, '')
SELECT gender, COUNT(*) FROM Customers GROUP BY gender;
SELECT gender FROM Customers GROUP BY gender HAVING COUNT(*) >= (SELECT AVG(c) FROM (SELECT COUNT(*) AS c FROM Customers GROUP BY gender));
